// VK branch of trend-scout. Pulls recent posts from the user's
// thematic VK communities (groups.get filtered by THEME; fallback
// list when the scan fails), scores them by engagement only and
// passes the top ones to Format Digest as `vk` items. VK items use
// the same shape and digest.json index space as RSS items, so a
// "post N" reply resolves them too.
// Errors degrade quietly: a rejected token (error 5) flips
// vk_status to 'auth_error', other failures are noted in vk_error
// and the RSS digest still goes out.
const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
const SEEN = STATE + '/trend_seen.json';

const src = $input.first().json || {};
const out = Object.assign({}, src, { vk: [], vk_status: 'ok' });
const token = ENV('VK_ACCESS_TOKEN');
if (!token) { out.vk_status = 'no_token'; return [{ json: out }]; }

const WINDOW_H = 48;   // only posts newer than this are candidates
const PER_GROUP = 2;   // top posts kept per community
const TOTAL_CAP = 6;   // max VK items per digest
const MAX_GROUPS = 8;  // wall.get calls per run
// pillar filter for the live subscription scan
const THEME = /n8n|automat|workflow|no-?code|react|front|javascript|typescript|program|algo|quant|trad|fintech|data ?scien|machine ?learn|devops|\bdev\b|\bit\b|\bai\b|\bml\b|hack|habr|science|tech|web|нейро|наук|техник|разработ|программ|трейд|алго|бирж|веб|айти/i;
// public walls used when groups.get is unreachable or matches nothing
const FALLBACK = ['habr_com', 'webstandards_ru', 'proglib', 'smart_lab'];

let seen = {};
try { seen = JSON.parse(fs.readFileSync(SEEN, 'utf8')); } catch (e) {}
// drop entries older than the 7d window, same as Format Digest
const nowMs = Date.now();
for (const k of Object.keys(seen)) {
  if (nowMs - seen[k] > 7 * 86400e3) delete seen[k];
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const lnp = (v, cap) => (v > 0 ? Math.min(1, Math.log1p(v) / Math.log1p(cap)) : 0);
const vkRaw = (method, params) => {
  const qs = Object.keys(params)
    .map((k) => k + '=' + encodeURIComponent(params[k])).join('&');
  return this.helpers.httpRequest({
    method: 'GET', json: true, timeout: 15000,
    url: 'https://api.vk.com/method/' + method + '?' + qs +
      '&v=5.199&access_token=' + encodeURIComponent(token)
  });
};
// one delayed retry on flood control (error 9)
const vk = async (method, params) => {
  const r = await vkRaw(method, params);
  if (r && r.error && r.error.error_code === 9) {
    await sleep(3000);
    return vkRaw(method, params);
  }
  return r;
};
const authError = (o, where) => {
  o.vk_status = 'auth_error';
  o.vk_error = where + ': token rejected (error 5) - refresh VK_ACCESS_TOKEN';
};

// -- resolve target communities ------------------------------------
let targets = [];
try {
  const g = await vk('groups.get', {
    user_id: ENV('VK_USER_ID') || '', extended: 1, count: 100
  });
  if (g && g.error) {
    if (g.error.error_code === 5) { authError(out, 'groups.get'); return [{ json: out }]; }
    out.vk_error = 'groups.get: ' + (g.error.error_msg || g.error.error_code);
  } else if (g && g.response && g.response.items) {
    targets = g.response.items
      .filter((c) => THEME.test((c.name || '') + ' ' + (c.screen_name || '')))
      .map((c) => ({ owner_id: -c.id, name: c.name || ('club' + c.id) }));
  }
} catch (e) {
  out.vk_error = 'groups.get: ' + String(e).slice(0, 120);
}
if (targets.length) out.vk_source = 'subscriptions';
else {
  targets = FALLBACK.map((d) => ({ domain: d }));
  out.vk_source = 'fallback';
}
targets = targets.slice(0, MAX_GROUPS);

// -- pull walls and score by engagement ----------------------------
// engagement mirrors the rss-reader log-normalized shape:
//   0.45 * comments/300 + 0.35 * likes/2000 + 0.2 * views/100000
const cutoff = Math.floor(Date.now() / 1000) - WINDOW_H * 3600;
const scored = [];
const groupErrs = [];
for (const t of targets) {
  const base = t.owner_id ? { owner_id: t.owner_id } : { domain: t.domain };
  const label = t.name || t.domain || String(t.owner_id);
  let r = null;
  try {
    r = await vk('wall.get', Object.assign({ count: 20, filter: 'owner' }, base));
  } catch (e) {
    groupErrs.push(label + ': ' + String(e).slice(0, 80));
    continue;
  }
  if (r && r.error) {
    if (r.error.error_code === 5) { authError(out, 'wall.get'); return [{ json: out }]; }
    groupErrs.push(label + ': ' + (r.error.error_msg || r.error.error_code));
    await sleep(400);
    continue;
  }
  const posts = ((r && r.response && r.response.items) || [])
    .filter((x) => x.date >= cutoff && !x.is_pinned && !x.marked_as_ads);
  // dedup BEFORE the per-group cap: a post already sent in a previous
  // digest must not occupy one of the PER_GROUP slots, otherwise
  // newer unseen posts ranked below it never reach the digest (same
  // order the RSS branch applies in Format Digest)
  const top = posts
    .filter((x) => !seen['vk:' + x.owner_id + '_' + x.id])
    .map((x) => ({
      post: x,
      eng: 0.45 * lnp(x.comments && x.comments.count, 300) +
        0.35 * lnp(x.likes && x.likes.count, 2000) +
        0.2 * lnp(x.views && x.views.count, 100000)
    }))
    .sort((a, b) => b.eng - a.eng)
    .slice(0, PER_GROUP);
  for (const s of top) {
    const x = s.post;
    const id = 'vk:' + x.owner_id + '_' + x.id;
    const text = String(x.text || '').replace(/\s+/g, ' ').trim();
    scored.push({
      id: id,
      title: text.slice(0, 110) || '(media post)',
      url: 'https://vk.com/wall' + x.owner_id + '_' + x.id,
      source: 'vk:' + label,
      published: new Date(x.date * 1000).toISOString(),
      metrics: {
        likes: x.likes ? x.likes.count : 0,
        comments: x.comments ? x.comments.count : 0,
        views: x.views ? x.views.count : 0,
        reposts: x.reposts ? x.reposts.count : 0
      },
      eng: s.eng,
      vk: true
    });
  }
  await sleep(400);
}

scored.sort((a, b) => b.eng - a.eng);
const picked = scored.slice(0, TOTAL_CAP);
for (const i of picked) {
  i.hype = Math.round(100 * Math.min(1, i.eng));
  delete i.eng;
}
out.vk = picked;
if (groupErrs.length) out.vk_errors = groupErrs.slice(0, 5);
if (!picked.length && out.vk_status === 'ok' && out.vk_error) out.vk_status = 'error';
return [{ json: out }];

const fs = require('fs');
const STATE = '/home/node/.n8n/state';
fs.mkdirSync(STATE, { recursive: true });
const SEEN = STATE + '/trend_seen.json';
const DIGEST = STATE + '/digest.json';
let seen = {};
try { seen = JSON.parse(fs.readFileSync(SEEN, 'utf8')); } catch (e) {}
const now = Date.now();
for (const k of Object.keys(seen)) {
  if (now - seen[k] > 7 * 86400e3) delete seen[k];
}
let chatId = null;
try { chatId = JSON.parse(fs.readFileSync(STATE + '/tg.json', 'utf8')).chat_id; } catch (e) {}

// rss-reader /curate already orders by hype desc; re-sort defensively
const items = (($input.first().json.items) || [])
  .slice()
  .sort((a, b) => (b.hype ?? b.score ?? 0) - (a.hype ?? a.score ?? 0));
const fresh = items.filter(i => i.id && !seen[i.id]);
const top = fresh.slice(0, 8);
// VK branch output (upstream "VK Top Posts" node)
const vkItems = (($input.first().json.vk) || [])
  .slice()
  .sort((a, b) => (b.hype ?? 0) - (a.hype ?? 0));
const vkStatus = $input.first().json.vk_status || 'ok';
const vkErr = $input.first().json.vk_error || '';
const vkErrs = $input.first().json.vk_errors || [];
const date = new Date().toISOString().slice(0, 10);
const fmtK = (v) => v >= 1000 ? (v / 1000).toFixed(1).replace(/\.0$/, '') + 'K' : String(v);

const lines = top.map((i, n) => {
  const m = i.metrics || {};
  const stats = [
    m.views ? 'views ' + fmtK(m.views) : '',
    m.comments ? 'comments ' + m.comments : '',
    m.votes ? 'votes ' + m.votes : ''
  ].filter(Boolean).join(' | ');
  return (n + 1) + '. [hype ' + (i.hype != null ? i.hype : '-') +
    (typeof i.score === 'number' ? ' | fit ' + i.score.toFixed(1) : '') + '] ' + i.title +
    '\n' + (i.source || '') + ' - ' + (i.url || '') +
    (stats ? '\n' + stats : '') +
    (i.angle ? '\nangle: ' + i.angle : '') +
    (n === 0 ? '\n> POST CANDIDATE' : '');
});

// VK items share the same index space so "post N" resolves them too
const vkLines = vkItems.map((i, n) => {
  const m = i.metrics || {};
  const stats = [
    'likes ' + fmtK(m.likes || 0),
    m.comments ? 'comments ' + m.comments : '',
    m.views ? 'views ' + fmtK(m.views) : ''
  ].filter(Boolean).join(' | ');
  return (top.length + n + 1) + '. [hype ' + (i.hype != null ? i.hype : '-') + ' | vk] ' +
    i.title +
    '\n' + (i.source || '') + ' - ' + (i.url || '') +
    (stats ? '\n' + stats : '');
});

// -- assemble item blocks -------------------------------------------
// The "VK communities" header rides on the first VK block so a chunk
// boundary never duplicates or orphans it. The skip note also covers
// the all-wall.get-failed case: groups.get can succeed while every
// wall.get fails, which populates only vk_errors and leaves
// vk_status 'ok' - without this the section vanished silently and an
// empty RSS day sent nothing at all.
const blocks = lines.slice();
if (vkLines.length) {
  blocks.push('VK communities\n\n' + vkLines[0]);
  for (const l of vkLines.slice(1)) blocks.push(l);
} else if (vkStatus === 'auth_error' || vkStatus === 'error' || vkErrs.length) {
  const reason = [vkErr, vkErrs.slice(0, 3).join('; ')]
    .filter(Boolean).join('; ');
  blocks.push('VK communities: skipped - ' + (reason || vkStatus));
}

// -- split into Telegram-safe chunks --------------------------------
// sendMessage rejects texts over 4096 chars; keep a margin and split
// on whole item blocks. The digest header goes on the first chunk,
// the reply hint on the last one, numbering stays global across the
// split, and section headers stay glued to their first item.
const MAX_TG = 3800;
const header = 'Trend digest ' + date + ' (' + (fresh.length + vkItems.length) +
  ' new: ' + fresh.length + ' rss' +
  (vkItems.length ? ', ' + vkItems.length + ' vk' : '') + ')';
const footer = 'Reply: post N - to generate hype-commentary draft on item N';
const chunks = [];
if (blocks.length) {
  let cur = header;
  for (const raw of blocks) {
    const b = raw.length > MAX_TG ? raw.slice(0, MAX_TG - 20) + ' ...[cut]' : raw;
    if ((cur + '\n\n' + b).length > MAX_TG) { chunks.push(cur); cur = b; }
    else cur = cur + '\n\n' + b;
  }
  if ((cur + '\n\n' + footer).length > MAX_TG) { chunks.push(cur); cur = footer; }
  else cur = cur + '\n\n' + footer;
  chunks.push(cur);
}

// cache digest items so a "post N" reply resolves to a stored item
// (VK items share the index space, stored under the same shape)
if (top.length || vkItems.length) {
  let digest = {};
  try { digest = JSON.parse(fs.readFileSync(DIGEST, 'utf8')); } catch (e) {}
  digest[date] = {};
  top.forEach((i, n) => { digest[date][String(n + 1)] = i; });
  vkItems.forEach((i, n) => { digest[date][String(top.length + n + 1)] = i; });
  const days = Object.keys(digest).sort().slice(-3);
  const pruned = {};
  for (const d of days) pruned[d] = digest[d];
  fs.writeFileSync(DIGEST, JSON.stringify(pruned, null, 1));
}

// trend_seen.json is NOT written here: the downstream "Mark Seen"
// node runs only after every Send Digest chunk succeeded, so a failed
// send keeps the items eligible for the next run instead of losing
// them after a partial or rejected delivery.
const seenIds = fresh.map((i) => i.id).concat(vkItems.map((i) => i.id));
if (!chunks.length) {
  return [{ json: { text: '', chat_id: chatId, count: 0, seen_ids: [] } }];
}
return chunks.map((t, n) => ({
  json: {
    text: t,
    chat_id: chatId,
    chunk: n + 1,
    chunks: chunks.length,
    count: fresh.length + vkItems.length,
    seen_ids: seenIds
  }
}));

// Persist trend_seen.json only after Send Digest has delivered every
// digest chunk. Send Digest is fail-stop, so this node is skipped on
// any sendMessage error and undelivered items stay eligible for the
// next run instead of being marked seen and silently dropped.
const fs = require('fs');
const STATE = '/home/node/.n8n/state';
fs.mkdirSync(STATE, { recursive: true });
const SEEN = STATE + '/trend_seen.json';
let seen = {};
try { seen = JSON.parse(fs.readFileSync(SEEN, 'utf8')); } catch (e) {}
const now = Date.now();
for (const k of Object.keys(seen)) {
  if (now - seen[k] > 7 * 86400e3) delete seen[k];
}
// Format Digest emits one item per chunk; each carries the same
// seen_ids list, so the first item is enough
const first = ($('Format Digest').first() || {}).json || {};
for (const id of (first.seen_ids || [])) seen[id] = now;
fs.writeFileSync(SEEN, JSON.stringify(seen));
return $input.all();
